{
  "justification": "Salience is dominated by welfare and public-service concerns (NHS, social care, education, housing, poverty), so Care and Equality receive the largest weights. Europe/immigration/defence elevate Loyalty (with some Authority), the economy/tax/prices/jobs point to Proportionality, and Sanctity is present but modest via morality, drugs and environmental purity; as this instrument records issues not direction, the weights reflect prominence rather than stance.",
  "foundations": [
    {
      "foundation": "care",
      "basis": "NHS/Hospitals/Healthcare (61%), Ageing population/Social care (12%), Housing (15%), Pollution/Environment (9%), Pensions/Social security (9%), Drug abuse (4%), Animal welfare (2%)",
      "weight": 0.321
    },
    {
      "foundation": "loyalty",
      "basis": "Common Market/EU/Europe (45%), Immigration (25%), Defence/Foreign affairs/International terrorism (10%), Nuclear weapons/Disarmament (3%), Scottish/Welsh Assembly/Devolution (2%), Countryside/Rural life (1%)",
      "weight": 0.229
    },
    {
      "foundation": "authority",
      "basis": "Crime/Law and order/Violence/Vandalism (10%), Lack of faith in govt/politics (4%), Morality/Individual behaviour/Lifestyle (4%), Local government/Council tax/Poll tax (2%), Nationalisation/Government control (2%), Privatisation (2%), Trade unions/Strikes (1%)",
      "weight": 0.067
    },
    {
      "foundation": "sanctity",
      "basis": "Morality/Individual behaviour/Lifestyle (4%), Drug abuse (4%), Pollution/Environment (9%), Animal welfare (2%)",
      "weight": 0.051
    },
    {
      "foundation": "equality",
      "basis": "Poverty/Inequality (15%), Low pay/Minimum wage/Fair wages (7%), Education/Schools (27%), Housing (15%), Race relations (3%), Public services in general (9%)",
      "weight": 0.202
    },
    {
      "foundation": "proportionality",
      "basis": "Economy/Economic situation (20%), Unemployment/Factory closure/Lack of industry (12%), Inflation/Prices (5%), Taxation (5%), Privatisation (2%), Nationalisation/Government control (2%), Pound/Exchange rate (1%), Petrol prices/Fuel (1%)",
      "weight": 0.13
    }
  ]
}

{
  "justification": "Europe overwhelmingly dominates salience while the electorate leans authoritarian, is slightly center-right, mildly pro-redistribution, and somewhat pro-EU integration. This implies strong Authority and Loyalty motives around order, borders, and group cohesion; moderate Care via health; balanced Equality and Proportionality on economics; and minimal Sanctity concerns.",
  "foundations": [
    {
      "foundation": "authority",
      "basis": "Derived authority–liberty mean 6.56 (authoritarian) with salience for terrorism (5.6%), crime (0.8%), defence (0.5%), and immigration (10.7%).",
      "weight": 0.24
    },
    {
      "foundation": "loyalty",
      "basis": "Europe dominates salience (44.4%) with immigration (10.7%), national identity/goals-loss (0.2%), and Scottish independence (0.5%).",
      "weight": 0.21
    },
    {
      "foundation": "care",
      "basis": "High salience of health (10.9%) and some concern for poverty (0.8%), welfare (0.6%), and social care (0.2%).",
      "weight": 0.19
    },
    {
      "foundation": "proportionality",
      "basis": "Slight center-right self-placement (5.16) and economy-general salience (5.5%) with Europe debates about contributions/fairness (44.4%).",
      "weight": 0.17
    },
    {
      "foundation": "equality",
      "basis": "Redistribution self-placement 4.56 (modestly pro-redistribution) and salience of inequality (1.1%), austerity (1.1%), poverty (0.8%).",
      "weight": 0.16
    },
    {
      "foundation": "sanctity",
      "basis": "Very low salience for morals (0.2%), gender/sexuality/family (0.0%), and environment (0.8%).",
      "weight": 0.03
    }
  ]
}

