{
  "justification": "Europe dominates issue salience while the electorate sits slightly right-of-centre on left–right, mildly pro-redistribution, socially more authoritarian (6.56), and somewhat pro-integration with the EU (6.03). These patterns suggest strong pulls from Authority and Loyalty (invoked in both national and supranational directions), meaningful Care via health, balanced Equality–Proportionality economic intuitions, and a lighter but present Sanctity signal from security/morals concerns.",
  "foundations": [
    {
      "foundation": "authority",
      "basis": "Derived authority–liberty mean 6.56 (more authoritarian), with Terrorism/Immigration salience and Europe debates invoking respect for rules and order.",
      "weight": 0.24
    },
    {
      "foundation": "loyalty",
      "basis": "Very high salience of Europe (44.4%), Immigration (10.7%) and Terrorism (5.6%), with EU integration mean 6.03 indicating coalition/ingroup boundary concerns.",
      "weight": 0.20
    },
    {
      "foundation": "care",
      "basis": "High salience of Health (10.9%) and some concern for inequality/poverty, plus redistribution self-placement leaning toward helping 'ordinary people' (4.56).",
      "weight": 0.18
    },
    {
      "foundation": "equality",
      "basis": "Economic redistribution placement at 4.56 suggests mild support for redistribution to ordinary people, alongside some salience for inequality/poverty/welfare.",
      "weight": 0.16
    },
    {
      "foundation": "proportionality",
      "basis": "Slight right-of-centre self-placement (5.16) and attention to Economy-general (5.5%), Taxation (0.2%) and Debt/deficit (0.3%) evoke merit/reward norms.",
      "weight": 0.14
    },
    {
      "foundation": "sanctity",
      "basis": "Terrorism and Immigration salience, small 'Morals' concern (0.2%) and Environment (0.8%) reflect purity/contamination and elevated-living themes.",
      "weight": 0.08
    }
  ]
}

{
  "justification": "Because this is an unprompted salience instrument with no direction, I infer orientation only from which issues align with GAL/TAN identity concerns, not from whether they are merely mentioned. Mentions of immigration, crime/law and order, defence/terrorism and related moral/discipline topics are collectively higher than clearly GAL-coded items like environment, race relations, and animal welfare, while the very large EU category is directionally mixed, so I assign a mild TAN tilt.",
  "poles": [
    {
      "pole": "tan",
      "basis": "Immigration; Crime/Law and order/Violence/Vandalism; Defence/Foreign affairs/International terrorism; Morality/Individual behaviour/Lifestyle; Drug abuse",
      "weight": 0.6
    },
    {
      "pole": "gal",
      "basis": "Pollution/Environment; Race relations; Animal welfare",
      "weight": 0.4
    }
  ]
}

{
  "justification": "The electorate leans authoritarian on the social authority–liberty scale (6.56/10), pointing toward TAN commitments to order and tradition. At the same time it is modestly pro–European integration (6.03/10), a GAL-consistent supranational openness, so overall it is TAN-leaning but tempered by GAL elements.",
  "poles": [
    {
      "pole": "tan",
      "basis": "Social position: authority–liberty derived scale mean 6.56 (higher=more authoritarian).",
      "weight": 0.62
    },
    {
      "pole": "gal",
      "basis": "European integration self-placement mean 6.03 (higher=more favourable to supranational integration).",
      "weight": 0.38
    }
  ]
}
